import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/maskreg.srczlE27.png",h=JSON.parse('{"title":"MaskReg","description":"","frontmatter":{},"headers":[{"level":1,"title":"MaskReg","slug":"maskreg"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"支持的型号","slug":"支持的型号"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/MaskReg.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/MaskReg.md"}'),r={name:"api/SIMD-API/基础API/Reg矢量计算/寄存器数据类型/MaskReg.md"};function i(p,a,d,c,g,o){return s(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="maskreg" tabindex="-1">MaskReg <a class="header-anchor" href="#maskreg" aria-label="Permalink to &quot;MaskReg&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>MaskReg用于指示在计算过程中哪些元素参与计算，宽度为<a href="./RegTensor.html">RegTensor</a>的八分之一（VL/8）。</p><p><img src="'+l+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, MaskPattern mode = MaskPattern::ALL, const RegTrait&amp; regTrait = RegTraitNumOne&gt;</span></span>
<span class="line"><span>__simd_callee__ inline MaskReg CreateMask();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template &lt;typename T, const RegTrait&amp; regTrait = RegTraitNumOne&gt;</span></span>
<span class="line"><span>__simd_callee__ inline MaskReg UpdateMask(uint32_t&amp; scalarValue);</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>模板参数。 Ascend 950PR/Ascend 950DT，支持的数据类型为b8/b16/b32/b64。</td></tr><tr><td>mode</td><td>输入</td><td>创建MaskReg的模式，enum class类型。 &lt;pre class=&quot;screen&quot; id=&quot;screen39202451285&quot;&gt;enum class MaskPattern { ALL, // 所有元素设置为True VL1, // 最低1个元素 VL2, // 最低2个元素 VL3, // 最低3个元素 VL4, // 最低4个元素 VL8, // 最低8个元素 VL16, // 最低16个元素 VL32, // 最低32个元素 VL64, // 最低64个元素 VL128, // 最低128个元素 M3, // 3的倍数 M4, // 4的倍数 H, // 最低一半元素 Q, // 最低四分之一元素 ALLF = 15 // 所有元素设置为false };&lt;/pre&gt;</td></tr><tr><td>regTrait</td><td>输入</td><td>当前仅针对b64/complex32数据类型生效，分为RegTraitNumOne和RegTraitNumTwo，含义和RegTensor的模板regTrait类型一致，配合RegTensor的regTrait一起使用。regTrait为RegTraitNumOne时，表明当前MaskReg的作用范围可覆盖至256B（一个VL的长度）。对于使用RegTraitNumOne的b64 RegTensor的指令，生成的b64 mask为每8位有效；RegTraitNumTwo表明当前MaskReg的作用范围可覆盖至512B（两个VL的长度），生成的b64 mask为每4位有效，作用于使用RegTraitNumTwo的b64 RegTensor的指令。该参数默认值为RegTraitNumOne。</td></tr><tr><td>scalarValue</td><td>输入/输出</td><td>矢量计算需要操作的元素的具体数量，生成对应的MaskReg，元素有效范围从0到VL_T（位宽为VL的T类型元素个数）。 执行完该函数后，scalarValue会减去VL_T。 scalarValue = (scalarValue &lt; VL_T) ? 0 : (scalarValue - VL_T)</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>MaskReg</p><h2 id="支持的型号" tabindex="-1">支持的型号 <a class="header-anchor" href="#支持的型号" aria-label="Permalink to &quot;支持的型号&quot;">​</a></h2><p>Ascend 950PR/Ascend 950DT</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Reg::RegTensor&lt;uint32_t&gt; srcReg;</span></span>
<span class="line"><span>AscendC::Reg::MaskReg mask0 = AscendC::Reg::CreateMask&lt;uint32_t,AscendC::Reg:: MaskPattern::ALL &gt;();</span></span>
<span class="line"><span>AscendC::Reg::MaskReg mask1;</span></span>
<span class="line"><span>uint32_t scalarValue = 127;</span></span>
<span class="line"><span>for (uint16_t i = 0; i &lt; 2; i++) {</span></span>
<span class="line"><span>    mask1 = AscendC::Reg::UpdateMask&lt;uint32_t&gt;(scalarValue);</span></span>
<span class="line"><span>    AscendC::Reg::LoadAlign&lt;T, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(srcReg, srcAddr, 0);</span></span>
<span class="line"><span>    AscendC::Reg::Adds(srcReg, srcReg, 1, mask0);</span></span>
<span class="line"><span>    AscendC::Reg::StoreAlign&lt;T, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(dst0Addr, srcReg, 0, mask0);</span></span>
<span class="line"><span>    AscendC::Reg::StoreAlign&lt;T, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(dst1Addr, srcReg, 0, mask1);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,17)])])}const R=e(r,[["render",i]]);export{h as __pageData,R as default};
